import {prophets,topics,tracks} from './catalog.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nativePlatform=window.Capacitor?.getPlatform?.();
const nativeAndroid=nativePlatform==='android';
const nativeMobile=nativeAndroid||nativePlatform==='ios';
const nativeBackup=nativeMobile?window.Capacitor.registerPlugin('ResearchBackup'):null;
const nativeAds=nativeAndroid?window.Capacitor.registerPlugin('PocketAds'):null;
let adsTestMode=false;
function hideAds(){if(nativeAds)nativeAds.hide().catch(()=>{});}
function renderAdTestControl(){
 if(!nativeAds||!adsTestMode||!['timeline','prophets','topics'].includes(view))return;
 main.insertAdjacentHTML('beforeend','<aside class="panel" id="ad-test-controls"><p><strong>Optional test advertisement</strong></p><p>This adult test build can connect to Google to show a demo banner. Google may process device and network information. Your research notes are not sent. <a href="privacy.html">Privacy details</a></p><button id="show-test-ad">Show Google test ad</button> <button id="hide-test-ad">Hide ad</button><p class="small" id="ad-test-status" role="status"></p></aside>');
}
let backupBusy=false;
const main=$('#main'),dialog=$('#detail');let db,meta,flat=[],language='both',track='origins',page=0,view='timeline',readerRefs=[],readerTitle='',detailRefs=[],detailPage=0,detailItem=null,searchResults=[],searchTerm='',deferredInstall=null;
const storage={get(k,f){try{return JSON.parse(localStorage.getItem('pq-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('pq-'+k,JSON.stringify(v));return true}catch{toast('Storage is unavailable or full. Export a backup before leaving.');return false}}};
const restored=storage.get('research',null);
let saved=restored?.saved||storage.get('saved',[]),notes=restored?.notes||storage.get('notes',[]);
const rawStore=storage.set.bind(storage);
storage.set=(key,value)=>['notes','saved'].includes(key)?rawStore('research',{notes:key==='notes'?value:notes,saved:key==='saved'?value:saved}):rawStore(key,value);language=storage.get('language','both');if(!['en','ur','ar','both'].includes(language))language='both';
let notebookTopic='';
const categoryName=id=>topics.find(t=>t.id===id)?.name||'Uncategorized';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',5000)}
function refsExpand(refs){const out=[];for(const r of refs){const m=/^(\d+):(\d+)(?:-(\d+))?$/.exec(r);if(!m)throw Error('Use references such as 2:30 or 2:30-39.');const s=+m[1],start=+m[2],end=+(m[3]||m[2]);if(!db.ar[s]||start<1||end<start||end>db.ar[s].length)throw Error('Verse reference outside the Quran: '+r);for(let v=start;v<=end;v++)out.push(s+':'+v)}return [...new Set(out)]}
const verseData=ref=>{const [s,v]=ref.split(':').map(Number);return {s,v,ar:db.ar[s][v-1].text,en:db.en[s][v-1].text,ur:db.ur[s][v-1].text,foot:db.ur[s][v-1].footnotes}};
function languageControl(id='language'){return `<label>Translation<select id="${id}" class="language-select"><option value="both" ${language==='both'?'selected':''}>English + Urdu</option><option value="en" ${language==='en'?'selected':''}>English · Pickthall</option><option value="ur" ${language==='ur'?'selected':''}>Urdu · Junagarhi</option><option value="ar" ${language==='ar'?'selected':''}>Arabic only</option></select></label>`}
function verse(ref){const x=verseData(ref);const related=topics.filter(t=>t.expanded.includes(ref));return `<article class="verse" data-ref="${ref}"><div class="verse-head"><span>${esc(meta.chapters[x.s-1].transliteration)} · ${ref}</span><div><button data-save="${ref}" class="${saved.includes(ref)?'saved-active':''}" aria-pressed="${saved.includes(ref)}">${saved.includes(ref)?'★ Saved':'☆ Save'}</button><button data-note="${ref}">Add note</button></div></div><p class="arabic" lang="ar" dir="rtl">${esc(x.ar)}</p>${(language==='both'?['en','ur']:language==='ar'?[]:[language]).map(lang=>`<p class="translation ${lang==='ur'?'urdu':''}" lang="${lang}" ${lang==='ur'?'dir="rtl"':''}>${esc(x[lang])}</p><small>${lang==='en'?'Marmaduke Pickthall · English translation':'Muhammad Junagarhi · QuranEnc.com · Urdu v1.1.3'}</small>`).join('')}${['ur','both'].includes(language)&&x.foot?`<details><summary>Translator’s notes · حواشی</summary><p class="translation urdu" lang="ur" dir="rtl">${esc(x.foot)}</p></details>`:''}<div class="verse-bottom"><a href="https://quran.com/${x.s}/${x.v}" target="_blank" rel="noopener">Read in context ↗</a>${related.map(t=>`<button data-topic="${t.id}">${esc(t.name)}</button>`).join('')}</div></article>`}
function pager(total,current,kind){return total>12?`<div class="pagination"><button data-page="${kind}:${current-1}" ${current===0?'disabled':''}>Previous</button><span class="small">${current*12+1}–${Math.min((current+1)*12,total)} of ${total}</span><button data-page="${kind}:${current+1}" ${(current+1)*12>=total?'disabled':''}>Next</button></div>`:''}
const intro=(eyebrow,title,desc)=>`<div class="intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div><div class="bismillah" lang="ar">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</div></div>`;
const searchForm=()=>`<form id="search-form" class="searchbar"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search the Quran and research index" placeholder="Search a prophet, theme, verse, or phrase…" value="${esc(searchTerm)}"><button type="submit">Search</button></form>`;
function render(){hideAds();const hash=location.hash.slice(1).split('?')[0]||'timeline';view=['timeline','prophets','topics','reader','revelation','notebook','saved','sources','search'].includes(hash)?hash:'timeline';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title='Pocket Quran · '+({timeline:'Timelines',reader:'Quran reader',notebook:'Research notebook'}[view]||view.charAt(0).toUpperCase()+view.slice(1));({timeline:renderTimeline,prophets:renderProphets,topics:renderTopics,reader:renderReader,revelation:renderRevelation,notebook:renderNotebook,saved:renderSaved,sources:renderSources,search:renderSearch}[view])();renderAdTestControl();}
function navigate(name){if(location.hash==='#'+name)render();else location.hash=name}
function renderTimeline(){const t=tracks[track];main.innerHTML=intro('EXPLORE THE CONNECTIONS','A journey through the Quran.','Follow the narratives. Discover shared themes. Return to the source.')+searchForm()+`<div class="stats"><span><strong>114</strong> surahs</span><span><strong>30</strong> juz</span><span><strong>25</strong> prophets indexed</span><span><strong>${topics.length}</strong> research categories</span></div><div class="tabs" role="group" aria-label="Timeline paths">${Object.entries(tracks).map(([k,t])=>`<button data-track="${k}" class="${track===k?'active':''}" aria-pressed="${track===k}">${t.name}</button>`).join('')}</div><div class="explorer"><section class="panel"><div class="section-row"><h2>${t.name}</h2><span class="pill amber">Relative sequence</span></div><p class="small">${t.description}</p><div class="timeline">${t.events.map(e=>`<div class="event"><div class="event-meta">${e.era}</div><button class="event-card" data-event="${e.id}"><div><h3>${e.title}</h3><p>${e.description}</p><div class="event-foot"><span class="pill">Quran</span><span>${e.refs.length} linked passages</span><span>Explore verses ↗</span></div></div><span class="arabic-name" lang="ar">${e.ar}</span></button></div>`).join('')}</div>${notes.filter(n=>n.track===track).length?`<div class="note"><strong>Your connected research</strong>${notes.filter(n=>n.track===track).map(n=>`<p style="margin:8px 0"><button data-research="${esc(n.id)}">${esc(n.title)}</button></p>`).join('')}</div>`:''}</section><aside class="panel guide"><span class="eyebrow">A SOURCE-FIRST JOURNEY</span><h3 style="margin-top:15px">Read across<br>the connections.</h3><p>Every story is a doorway into the verses, their context, and the themes they share.</p><div class="guide-item"><strong>01 &nbsp; Choose a path</strong><p>Creation, prophetic narratives, revelation, or the Hereafter.</p></div><div class="guide-item"><strong>02 &nbsp; Open an event</strong><p>Read Arabic with English and Urdu, and follow the references.</p></div><div class="guide-item"><strong>03 &nbsp; Build your research</strong><p>Save a verse or connect your own sourced notes.</p></div><div class="note">Dates are left unknown where the sources do not establish them.</div><a href="#sources">Our research method ↗</a></aside></div>`}
function renderProphets(){main.innerHTML=intro('PEOPLE & NARRATIVES','The prophets.','Open a name to explore selected Quranic passages. Peace be upon them all.')+`<div class="note">This is a study directory, not a definitive chronological order. Passage lists are a starter index and are not exhaustive. Dhul-Kifl is included in the commonly taught list; his identity and prophetic status are discussed by scholars.</div><div class="grid">${prophets.map(p=>`<button class="prophet-card" data-prophet="${p.id}"><div><h3>${p.name}</h3><small>${p.alias!==p.name?p.alias+' · ':''}${p.refs.length} passages</small></div><span lang="ar">${p.ar}</span></button>`).join('')}</div>`}
function renderTopics(){main.innerHTML=intro('ONE VERSE, MANY CONNECTIONS','30 research categories.','Explore guidance across surahs. A verse can connect to more than one theme.')+`<p class="note">Proposed structure for your 30 thematic research chapters—not the 30 juz and not recovered chapter titles. ${new Set(topics.flatMap(t=>t.expanded)).size} of 6,236 verses currently have selected category links. Categories overlap; comprehensive indexing and scholarly review remain in progress.</p><div class="grid">${topics.map((t,i)=>`<button class="topic-card" data-topic="${t.id}"><div class="card-number">${String(i+1).padStart(2,'0')} / CATEGORY</div><h3>${t.name}</h3><p>${t.description}</p><small>${t.expanded.length} indexed verses · ${notes.filter(n=>n.topic===t.id).length} research notes &nbsp; ↗</small></button>`).join('')}</div>`}
function readerControls(){return `<div class="controls"><label>Surah<select id="surah"><option value="">Select surah</option>${meta.chapters.map(c=>`<option value="${c.id}">${c.id}. ${c.transliteration} · ${c.name}</option>`).join('')}</select></label><label>Juz<select id="juz"><option value="">Select juz</option>${meta.indexes.juzs.map(j=>`<option value="${j.index}">Juz ${j.index} · ${j.sura}:${j.aya}</option>`).join('')}</select></label>${languageControl()}</div>`}
function setSurah(s){readerRefs=db.ar[s].map(v=>s+':'+v.verse);readerTitle=meta.chapters[s-1].transliteration+' · '+meta.chapters[s-1].translation;page=0;renderReader();$('#surah').value=s}
function renderReader(){if(!readerRefs.length){readerRefs=db.ar[1].map(v=>'1:'+v.verse);readerTitle='Al-Faatiha · The Opening'}main.innerHTML=intro('THE COMPLETE TEXT','Quran reader.','Arabic Quran with English and Urdu translations. Browse by surah or juz, or search the full text.')+searchForm()+readerControls()+`<div class="section-row"><h2>${esc(readerTitle)}</h2><span class="small">${readerRefs.length} verses</span></div><div class="verses">${readerRefs.slice(page*12,page*12+12).map(verse).join('')}</div>${pager(readerRefs.length,page,'reader')}`}
function renderRevelation(){main.innerHTML=intro('REVELATION CONTEXT','Meccan & Medinan.','Browse the traditional surah-level classification preserved in the source metadata.')+`<div class="note warning">These classifications do not establish the exact revelation order of every verse. Some surahs include passages associated with different periods, and scholarly classifications can differ.</div><div class="controls"><label>Period<select id="period"><option value="all">All surahs</option><option value="meccan">Meccan</option><option value="medinan">Medinan</option></select></label><button data-revelation-track>Open revelation timeline</button></div><div id="revelation-list"></div>`;revelationList('all')}
function revelationList(type){$('#revelation-list').innerHTML=`<div class="chapter-list">${meta.chapters.filter(c=>type==='all'||c.type===type).map(c=>`<button data-surah="${c.id}"><strong>${c.id}. ${c.transliteration}</strong><br><small>${c.type==='meccan'?'Meccan':'Medinan'} · ${c.total_verses} verses</small></button>`).join('')}</div>`}
function openDetail(item){hideAds();detailItem=item;detailRefs=refsExpand(item.refs);detailPage=0;drawDetail();if(!dialog.open)dialog.showModal()}
function drawDetail(){const item=detailItem;$('#detail-body').innerHTML=`<h2 id="detail-title">${esc(item.title||item.name)} ${item.ar?`<span lang="ar">· ${item.ar}</span>`:''}</h2>${item.description?`<p class="muted">${esc(item.description)}</p>`:''}<p class="small">Selected passages: ${item.refs.map(esc).join(' · ')}. ${detailRefs.length} unique verses. This index is not exhaustive.</p>${item.hadith?.length?`<div class="note"><strong>Related hadith · separate source</strong>${item.hadith.map(h=>`<p style="margin:10px 0 0"><a href="${h.url}" target="_blank" rel="noopener">${h.label} ↗</a><br>${h.note}</p>`).join('')}</div>`:''}${topics.some(t=>t.id===item.id)?`<p><button data-category-notes="${item.id}">Research in this category · ${notes.filter(n=>n.topic===item.id).length} notes</button></p>`:''}<div class="controls">${languageControl('detail-language')}</div>${detailRefs.slice(detailPage*12,detailPage*12+12).map(verse).join('')}${pager(detailRefs.length,detailPage,'detail')}`}
function renderSaved(){const valid=saved.filter(ref=>{try{return refsExpand([ref]).length===1}catch{return false}});main.innerHTML=intro('YOUR READING COLLECTION','Saved verses.','Keep passages close for further study. Saved on this device; included in your notebook backup.')+(valid.length?`<div class="controls">${languageControl()}</div><div class="verses">${valid.slice(page*12,page*12+12).map(verse).join('')}</div>${pager(valid.length,page,'saved')}`:'<div class="empty"><h2>Your collection starts with one verse.</h2><p>Choose Save beside any verse in the reader or a timeline.</p><a href="#reader">Open the Quran reader</a></div>')}
function renderSearch(){const matchedProphets=prophets.filter(p=>norm([p.name,p.alias,p.ar].join(' ')).includes(norm(searchTerm)));const matchedTopics=topics.filter(t=>norm(t.name+' '+t.description).includes(norm(searchTerm)));main.innerHTML=intro('SEARCH THE CONNECTIONS','Search results.',`Search Arabic, English, Urdu, or a reference such as 2:255.`)+searchForm()+`<div class="inline-links">${matchedProphets.map(p=>`<button data-prophet="${p.id}">${p.name} · Prophet</button>`).join('')}${matchedTopics.map(t=>`<button data-topic="${t.id}">${t.name} · Theme</button>`).join('')}</div><div class="section-row" style="margin-top:22px"><h2>${searchResults.length} verse matches</h2>${languageControl()}</div>`+(searchResults.length?`<div class="verses">${searchResults.slice(page*12,page*12+12).map(verse).join('')}</div>${pager(searchResults.length,page,'search')}`:'<div class="empty"><p>No matching verses. Try another spelling, a shorter phrase, or a reference such as 2:30.</p></div>')}
function norm(t){return String(t).normalize('NFKD').replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').toLowerCase()}
function search(q){searchTerm=q.trim();if(!searchTerm){toast('Enter a phrase, name, or verse reference.');return}page=0;try{searchResults=/^\d+:/.test(searchTerm)?refsExpand([searchTerm]):flat.filter(v=>v.search.includes(norm(searchTerm))).map(v=>v.ref)}catch(e){toast(e.message);return}navigate('search')}
function renderNotebook(){const filteredNotes=notes.filter(n=>!notebookTopic||n.topic===notebookTopic);main.innerHTML=intro('YOUR RESEARCH, CONNECTED','Research notebook.','Attach your findings to verses, themes, and timeline paths. Your original work remains distinct from the Quranic text.')+`<p class="note">Stored on this device, without cloud synchronization. Export regularly. Your research since 2015 has not yet been imported.</p><div class="notebook-tools"><button class="primary" id="new-note">+ New research note</button><button id="export-notes">Export backup</button><button id="import-notes">Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="controls"><label>Research category<select id="notebook-category"><option value="">All categories</option>${topics.map(t=>`<option value="${t.id}" ${notebookTopic===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><span class="small">${filteredNotes.length} research notes</span></div><section id="note-editor" class="panel" hidden></section><div id="entries">${filteredNotes.length?filteredNotes.map(n=>`<article class="panel research-entry"><div class="section-row"><h3>${esc(n.title)}</h3><span class="pill amber">Research draft</span></div><p class="small">${esc(categoryName(n.topic))}${n.chapter?' · Original label: '+esc(n.chapter):''} · ${esc(tracks[n.track]?.name||'No timeline')}</p><p class="entry-body">${esc(n.body)}</p>${n.source?`<p class="small"><strong>Source:</strong> ${esc(n.source)}<br><strong>Evidence:</strong> ${esc(n.evidence||'Research note')}</p>`:''}<div class="section-row"><div class="inline-links">${n.refs.map(ref=>`<button data-open-ref="${ref}">${ref}</button>`).join('')}</div><div><button data-edit-note="${esc(n.id)}">Edit</button> <button class="danger" data-delete-note="${esc(n.id)}">Delete</button></div></div></article>`).join(''):'<div class="empty"><h2>A home for your years of research.</h2><p>Start with one finding. Add a source and connect its verses to a research category.</p></div>'}</div>`}
function editNote(id,ref){const n=notes.find(n=>n.id===id)||{id:'',title:'',body:'',refs:ref?[ref]:[],chapter:'',source:'',evidence:'Research note',topic:notebookTopic,track:''};$('#note-editor').hidden=false;$('#note-editor').innerHTML=`<h2>${n.id?'Edit research note':'New research note'}</h2><form id="note-form" data-id="${esc(n.id)}"><div class="form-grid"><label class="full">Title<input name="title" required maxlength="200" value="${esc(n.title)}"></label>${n.chapter?`<label>Original chapter label<input name="chapter" maxlength="100" value="${esc(n.chapter)}"></label>`:'<input type="hidden" name="chapter" value="">'}<label>Research category<select name="topic"><option value="">General / uncategorized</option>${topics.map(t=>`<option value="${t.id}" ${n.topic===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><label>Timeline path<select name="track"><option value="">No timeline assigned</option>${Object.entries(tracks).map(([k,t])=>`<option value="${k}" ${n.track===k?'selected':''}>${t.name}</option>`).join('')}</select></label><label>Evidence type<select name="evidence">${['Research note','Quran interpretation','Hadith report','Historical source','Scholarly commentary'].map(x=>`<option ${n.evidence===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full">Verse references · comma separated<input name="refs" placeholder="2:30-39, 7:11" value="${esc(n.refs.join(', '))}"></label><label class="full">Source citation · book, page, URL, or hadith number<input name="source" maxlength="2000" value="${esc(n.source)}"></label><label class="full">Your research note<textarea name="body" required maxlength="20000">${esc(n.body)}</textarea></label></div><p class="small">These 30 proposed categories organize your thematic research; they are separate from surahs and juz. Existing chapter labels are preserved without guessing their meaning. For hadith, record the collection, number, grading and the scholar or edition providing that grading.</p><button class="primary" type="submit">Save research note</button> <button type="button" id="cancel-note">Cancel</button></form>`;$('#note-editor').scrollIntoView({block:'start',behavior:'smooth'});$('#note-form input').focus()}
async function exportNotes(){if(backupBusy)return;const data=JSON.stringify({format:'ProjectQuran',version:1,exportedAt:new Date().toISOString(),notes,saved},null,2);if(new Blob([data]).size>10*1024*1024){toast('Backup exceeds the 10 MB import limit. Split your research before export.');return}if(nativeBackup){backupBusy=true;try{await nativeBackup.exportFile({data});toast('Backup saved to your chosen location.')}catch(e){toast(e.code==='CANCELLED'?'Export cancelled. Your research is unchanged.':e.message||'Backup could not be saved.')}finally{backupBusy=false}return}const blob=new Blob([data],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Pocket-Quran-research-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup exported. Keep a copy outside this device.')}
async function importNotes(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup is too large (maximum 10 MB).');const x=JSON.parse(await file.text());if(x.format!=='ProjectQuran'||x.version!==1||!Array.isArray(x.notes)||!Array.isArray(x.saved))throw Error('Use a ProjectQuran version 1 JSON backup.');if(x.notes.length>10000)throw Error('This backup has too many notes.');const clean=x.notes.map(n=>{if(!n||typeof n.title!=='string'||!n.title.trim()||typeof n.body!=='string'||!Array.isArray(n.refs)||n.title.length>200||n.body.length>20000)throw Error('Invalid research note in backup.');refsExpand(n.refs);return {id:crypto.randomUUID(),title:n.title,body:n.body,refs:n.refs,chapter:typeof n.chapter==='string'?n.chapter.slice(0,100):'',source:typeof n.source==='string'?n.source.slice(0,2000):'',evidence:typeof n.evidence==='string'?n.evidence.slice(0,100):'Research note',topic:topics.some(t=>t.id===n.topic)?n.topic:'',track:tracks[n.track]?n.track:'',updatedAt:new Date().toISOString()}});const importedSaved=refsExpand(x.saved);const merged=[...notes];let count=0;for(const n of clean){if(!merged.some(o=>['title','body','chapter','source','evidence','topic','track'].every(k=>(o[k]||'')===(n[k]||''))&&JSON.stringify(o.refs)===JSON.stringify(n.refs))){merged.push(n);count++}}const mergedSaved=[...new Set([...saved,...importedSaved])];if(!rawStore('research',{notes:merged,saved:mergedSaved}))return;notes=merged;saved=mergedSaved;renderNotebook();toast(`Imported ${count} new notes. Existing notes were preserved.`)}catch(e){toast('Import failed: '+e.message)}}
async function chooseImport(){if(!nativeBackup){$('#import-file').click();return}if(backupBusy)return;backupBusy=true;try{const result=await nativeBackup.importFile();await importNotes(new Blob([result.data],{type:'application/json'}))}catch(e){toast(e.code==='CANCELLED'?'Import cancelled. Your research is unchanged.':e.message||'Backup could not be opened.')}finally{backupBusy=false}}
window.projectQuranBack=()=>{if(dialog.open){dialog.close();return true}if($('#install-help').open){$('#install-help').close();return true}if(view!=='timeline'){navigate('timeline');return true}return false};
function renderSources(){main.innerHTML=intro('TRANSPARENCY & CARE','Sources & research method.','The text, its interpretation, and your research are different layers.')+`<article class="panel prose"><h2>What is included</h2><p>The complete Quran text in 114 surahs and 6,236 numbered verses, English and Urdu translations, 30 juz boundaries, a selected index for 25 prophets and 30 proposed research categories, and four study paths. The topic and event references are editorial starting points, not an exhaustive classification or a scholarly certification.</p><h2>Text and translations</h2><ul class="source-list"><li><strong>Arabic:</strong> Tanzil Uthmani text v1.1. Copyright © 2007–2021 Tanzil Project, <a href="https://tanzil.net/docs/text_license" target="_blank" rel="noopener">CC BY 3.0 with verbatim-text conditions</a>. Arabic strings are displayed without edits. <a href="https://tanzil.net" target="_blank" rel="noopener">Tanzil.net</a>.</li><li><strong>English:</strong> Marmaduke Pickthall, <em>The Meaning of the Glorious Koran</em> (1930). Translation of meanings, not a replacement for the Arabic Quran.</li><li><strong>Urdu:</strong> Muhammad Junagarhi, Urdu translation with notes, <a href="https://quranenc.com/en/browse/urdu_junagarhi" target="_blank" rel="noopener">QuranEnc.com</a>, edition v1.1.3. Translation and accompanying notes are preserved. Publisher: King Fahd Glorious Quran Printing Complex (translation of Muhammad Junagarhi; commentary of Salahuddin Yusuf). Refer to the publisher for corrections and updated editions; this bundled snapshot does not update automatically.</li><li><strong>Metadata:</strong> Tanzil Quran metadata for surahs, juz boundaries, and traditional Meccan/Medinan classifications.</li><li><strong>Distribution:</strong> Licensed-source files from <a href="https://github.com/risan/quran-json" target="_blank" rel="noopener">risan/quran-json</a>, retrieved 18 September 2026. <a href="sources.json" target="_blank">Detailed provenance</a> · <a href="DATA-LICENSE.txt" target="_blank">Dataset license</a> · <a href="TANZIL-LICENSE.txt" target="_blank">Tanzil notice</a>.</li></ul><h2>Chronology and evidence</h2><p>The timelines are conceptual reading paths. They do not assign invented dates to creation, early prophets, or the Hereafter. The prophets directory avoids claiming a definitive order. A narration’s subject, the occasion of revelation, and the date of revelation must be recorded separately. Meccan/Medinan labels are surah-level metadata, not an exact sequence of verses.</p><p>Quranic references and hadith references appear separately. Related reports link to their collection and number on Sunnah.com; the original report and its context should be consulted. A future expanded hadith catalogue requires an explicit grading source and scholarly review, especially where reports conflict. No generated wording is presented as Quran or hadith.</p><h2>Editorial review before wider publication</h2><p>Verify each new connection against the complete passage and recognized commentary. Record the researcher, source edition, reference, uncertainty, and reviewer. Alternative interpretations can coexist as attributed research. Your notebook entries remain labelled research drafts.</p><h2>Your research and privacy</h2><p>Notes and bookmarks stay in local storage on this device. There are no automatic research uploads. Android test builds include an optional Google test banner; Google may process device and network information when you request it. Notes and verse selections are not passed to the advertising plugin. Read the <a href="privacy.html">privacy notice</a>. Clearing app/browser data or uninstalling the app removes local notes. Export backups regularly and import them on another device. External source links open third-party websites.</p><h2>Mobile and offline use</h2><p>Install from your browser’s menu or use the Install app button. The service worker caches the app and all three text datasets. Wait for the offline-ready notification on the first visit. Installation depends on browser support. The website is an installable web app. The Android test build bundles all three text datasets for offline use and saves backups through the system file picker. It is not a store release.</p><h2>The next research layer</h2><p>Your original work since 2015 is not yet in this app. The notebook uses 30 proposed thematic research categories, separately from the Quran’s 30 juz. The category titles are a new editorial proposal, not recovered titles from the original research. Earlier numbered chapter labels are preserved when present. Import your notes through the documented backup format, or provide the original Word, PDF, spreadsheet, or scanned research for a sourced migration. Wider Islamic history and comprehensive verse tagging should be added from those materials with review.</p></article>`}

document.addEventListener('click',e=>{if(e.target.closest('a'))hideAds();const b=e.target.closest('button');if(!b)return;
if(b.dataset.track){track=b.dataset.track;renderTimeline()}
if(b.dataset.event)openDetail(tracks[track].events.find(x=>x.id===b.dataset.event));
if(b.dataset.prophet)openDetail(prophets.find(x=>x.id===b.dataset.prophet));
if(b.dataset.topic)openDetail(topics.find(x=>x.id===b.dataset.topic));
if(b.dataset.openRef)openDetail({title:'Quran '+b.dataset.openRef,refs:[b.dataset.openRef]});
if(b.dataset.save){const r=b.dataset.save,next=saved.includes(r)?saved.filter(x=>x!==r):[...saved,r];if(storage.set('saved',next)){saved=next;document.querySelectorAll(`[data-save="${r}"]`).forEach(el=>{el.textContent=saved.includes(r)?'★ Saved':'☆ Save';el.classList.toggle('saved-active',saved.includes(r));el.setAttribute('aria-pressed',saved.includes(r))});if(view==='saved')renderSaved();toast(saved.includes(r)?'Verse saved on this device.':'Verse removed from saved collection.')}}
if(b.dataset.note){dialog.close();history.replaceState(null,'','#notebook');render();editNote(null,b.dataset.note)}
if(b.dataset.page){const [kind,n]=b.dataset.page.split(':');if(kind==='detail'){detailPage=+n;drawDetail();dialog.scrollTop=0}else{page=+n;render();main.scrollIntoView({block:'start'})}}
if(b.dataset.surah){history.replaceState(null,'','#reader');render();setSurah(+b.dataset.surah)}
if(b.hasAttribute('data-revelation-track')){track='revelation';navigate('timeline')}
if(b.dataset.research){history.replaceState(null,'','#notebook');render();editNote(b.dataset.research)}
if(b.dataset.categoryNotes){notebookTopic=b.dataset.categoryNotes;dialog.close();history.replaceState(null,'','#notebook');render()}
if(b.dataset.editNote)editNote(b.dataset.editNote);
if(b.dataset.deleteNote&&confirm('Delete this research note from this device? Export a backup first if needed.')){const next=notes.filter(n=>n.id!==b.dataset.deleteNote);if(storage.set('notes',next)){notes=next;renderNotebook()}}
if(b.id==='show-test-ad'){nativeAds.showTestBanner().then(()=>{const s=$('#ad-test-status');if(s)s.textContent='Test ad requested. Internet is needed; if no ad is available, reading remains available.'}).catch(e=>toast(e.message));}if(b.id==='hide-test-ad')hideAds();
if(b.id==='new-note')editNote();if(b.id==='cancel-note')$('#note-editor').hidden=true;if(b.id==='export-notes')exportNotes();if(b.id==='import-notes')chooseImport();
});
document.addEventListener('change',e=>{if(e.target.id==='notebook-category'){notebookTopic=e.target.value;renderNotebook()}
if(e.target.classList.contains('language-select')){language=e.target.value;storage.set('language',language);if(dialog.open)drawDetail();else render()}
if(e.target.id==='surah'&&e.target.value)setSurah(+e.target.value);
if(e.target.id==='juz'&&e.target.value){const j=+e.target.value,from=meta.indexes.juzs[j-1],to=meta.indexes.juzs[j];const key=(s,v)=>s*1000+v;readerRefs=flat.filter(x=>key(x.s,x.v)>=key(from.sura,from.aya)&&(!to||key(x.s,x.v)<key(to.sura,to.aya))).map(x=>x.ref);readerTitle='Juz '+j;page=0;renderReader();$('#juz').value=j}
if(e.target.id==='period')revelationList(e.target.value);if(e.target.id==='import-file')importNotes(e.target.files[0])});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();search($('#search').value)}if(e.target.id==='note-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const refs=data.refs.split(',').map(r=>r.trim()).filter(Boolean);refsExpand(refs);if(!data.title.trim()||!data.body.trim())throw Error('Add a title and research text.');const n={...data,refs,id:e.target.dataset.id||crypto.randomUUID(),updatedAt:new Date().toISOString()};const next=notes.some(x=>x.id===n.id)?notes.map(x=>x.id===n.id?n:x):[n,...notes];if(storage.set('notes',next)){notes=next;renderNotebook();toast('Research note saved on this device.')}}catch(err){toast(err.message)}}});
$('#close-detail').onclick=()=>dialog.close();$('#close-install').onclick=()=>$('#install-help').close();$('#install').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else $('#install-help').showModal()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});window.addEventListener('hashchange',()=>{page=0;render();window.scrollTo(0,0)});
async function boot(){try{if(nativeAds){try{adsTestMode=(await nativeAds.status()).testMode}catch{adsTestMode=false}}const [ar,en,ur,m]=await Promise.all(['arabic','english','urdu','metadata'].map(async n=>{const r=await fetch('./'+n+'.json');if(!r.ok)throw Error('Text file unavailable');return r.json()}));db={ar,en,ur};meta=m;topics.forEach(t=>t.expanded=refsExpand(t.refs));flat=Object.entries(ar).filter(([s])=>/^\d+$/.test(s)).flatMap(([s,vs])=>vs.map(v=>({s:+s,v:v.verse,ref:s+':'+v.verse,search:norm(v.text+' '+en[s][v.verse-1].text+' '+ur[s][v.verse-1].text)})));render();if(nativeMobile){$('#install').hidden=true;$('#connection').textContent='Offline Quran · bundled with this app';}if(!nativeMobile&&'serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='OFFLINE_READY'){$('#connection').textContent='Ready for offline reading';toast('Quran text and app are ready for offline reading.')}if(e.data==='OFFLINE_FAILED')toast('Offline preparation did not finish. Keep this page online and reload to retry.')});navigator.serviceWorker.register('./sw.js').then(async r=>{await navigator.serviceWorker.ready;(r.active||navigator.serviceWorker.controller)?.postMessage('CHECK_OFFLINE')}).catch(()=>{$('#connection').textContent='Online reading'})}}catch(e){main.innerHTML='<div class="empty"><h2>The Quran text could not load.</h2><p>Please reconnect and reload. Your saved research has not been changed.</p><button id="retry">Retry</button></div>';$('#retry').onclick=boot}}
boot();
